import math

def check_equation(a, b, c):
    # Check triangle inequality first
    if a + b <= c or b + c <= a or c + a <= b:
        return False

    # Calculate LHS: a^2 * b^2
    LHS = a**2 * b**2

    # Calculate RHS: 2 * (a + b - c) * (b + c - a) * (c + a - b)
    term1 = a + b - c
    term2 = b + c - a
    term3 = c + a - b

    RHS = 2 * term1 * term2 * term3

    return LHS == RHS

solutions = []
max_perimeter = 0

# Increased search limit
MAX_SIDE = 20

# Iterate over all combinations a, b, c where 1 <= a, b, c <= MAX_SIDE
# We iterate independently to find all solutions, then store unique sets.

found_triples = set()

for a in range(1, MAX_SIDE + 1):
    for b in range(1, MAX_SIDE + 1):
        for c in range(1, MAX_SIDE + 1):
            if check_equation(a, b, c):
                # Normalize the triple to store unique triangles {a, b, c}
                sides = tuple(sorted((a, b, c)))
                if sides not in found_triples:
                    found_triples.add(sides)
                    perimeter = a + b + c

                    if perimeter > max_perimeter:
                        max_perimeter = perimeter

                    solutions.append((a, b, c, perimeter))

print(f"Found solutions up to MAX_SIDE={MAX_SIDE}:")
if solutions:
    # Displaying only the unique sorted side combinations and perimeters for clarity
    unique_solutions = {}
    for a_sol, b_sol, c_sol, p in solutions:
        sides = tuple(sorted((a_sol, b_sol, c_sol)))
        unique_solutions[sides] = p

    print("\nUnique Solutions (a, b, c sides, a+b+c):")
    for sides, p in unique_solutions.items():
        print(f"({sides[0]}, {sides[1]}, {sides[2]}, {p})")

    print(f"\nMaximum perimeter found: {max_perimeter}")
else:
    print("No solutions found up to MAX_SIDE={MAX_SIDE}.")

def check_equation_q2(Pa, Pb, Pc):
    # Check triangle inequality
    if Pa + Pb <= Pc or Pb + Pc <= Pa or Pc + Pa <= Pb:
        return False

    # LHS: Pa^2 * Pb^2
    LHS = Pa**2 * Pb**2

    # RHS: 4 * (Pa + Pb - Pc) * (Pb + Pc - Pa) * (Pc + Pa - Pb)
    term1 = Pa + Pb - Pc
    term2 = Pb + Pc - Pa
    term3 = Pc + Pa - Pb

    RHS = 4 * term1 * term2 * term3

    return LHS == RHS

solutions = []
max_perimeter = 0

# Search limit for numerators P_i
MAX_P = 30

found_triples = set()

for Pa in range(1, MAX_P + 1):
    for Pb in range(1, MAX_P + 1):
        for Pc in range(1, MAX_P + 1):
            if check_equation_q2(Pa, Pb, Pc):
                # Normalize the triple to store unique triangles {Pa, Pb, Pc}
                sides_P = tuple(sorted((Pa, Pb, Pc)))
                if sides_P not in found_triples:
                    found_triples.add(sides_P)

                    # Perimeter of the original triangle a, b, c is (Pa+Pb+Pc)/2
                    perimeter = (Pa + Pb + Pc) / 2.0

                    if perimeter > max_perimeter:
                        max_perimeter = perimeter

                    solutions.append((Pa, Pb, Pc, perimeter))

print(f"Found solutions for q=2 up to P_i={MAX_P}:")
if solutions:
    # Displaying only the unique sorted side combinations and perimeters for clarity
    unique_solutions = {}
    for Pa_sol, Pb_sol, Pc_sol, p in solutions:
        sides_P = tuple(sorted((Pa_sol, Pb_sol, Pc_sol)))
        # The actual side lengths are (Pa/2, Pb/2, Pc/2)
        a, b, c = sides_P[0]/2.0, sides_P[1]/2.0, sides_P[2]/2.0
        unique_solutions[sides_P] = (p, (a, b, c))

    print("\nUnique Solutions (Pa, Pb, Pc, Perimeter, (a, b, c)):")
    for sides_P, data in unique_solutions.items():
        p, sides_abc = data
        print(f"P-sides: {sides_P}, Perimeter: {p}, Sides (a, b, c): {sides_abc}")

    print(f"\nMaximum perimeter found: {max_perimeter}")
else:
    print("No solutions found for q=2 up to P_i={MAX_P}.")
